package com.nm.fragmentsclean.experienceContext.read.adapters.primary.springboot.controllers;
import com.nm.fragmentsclean.experienceContext.read.*;import com.nm.fragmentsclean.experienceContext.read.projections.*;import java.util.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;
@RestController public final class ReadExperienceController{private final ListCoffeeExperiencesQueryHandler coffee;private final ListMyExperiencesQueryHandler mine;private final ListExperienceModerationReportsQueryHandler moderation;public ReadExperienceController(ListCoffeeExperiencesQueryHandler coffee,ListMyExperiencesQueryHandler mine,ListExperienceModerationReportsQueryHandler moderation){this.coffee=coffee;this.mine=mine;this.moderation=moderation;}@GetMapping("/api/coffees/{coffeeId}/experiences")ExperiencePage coffee(@PathVariable UUID coffeeId,@RequestParam(required=false)String cursor,@RequestParam(defaultValue="20")int limit,@AuthenticationPrincipal Jwt jwt){return coffee.handle(new ListCoffeeExperiencesQuery(user(jwt),coffeeId,cursor,limit));}@GetMapping("/api/users/me/experiences")ExperiencePage mine(@RequestParam(required=false)String cursor,@RequestParam(defaultValue="20")int limit,@AuthenticationPrincipal Jwt jwt){return mine.handle(new ListMyExperiencesQuery(user(jwt),cursor,limit));}@GetMapping("/api/admin/experience-moderation/reports")List<ExperienceModerationReportView> moderation(@RequestParam(defaultValue="OPEN")String status,@RequestParam(defaultValue="50")int limit){return moderation.handle(status,limit);}@ExceptionHandler(IllegalArgumentException.class)@ResponseStatus(org.springframework.http.HttpStatus.BAD_REQUEST)Map<String,String> invalidQuery(IllegalArgumentException error){return Map.of("error","INVALID_QUERY","reason",error.getMessage());}private static UUID user(Jwt jwt){return UUID.fromString(jwt.getSubject());}}
